import Razorpay from "razorpay";
import crypto from "crypto";
import { mysupabase } from "@/Supabase/SupabaseConfig";

// Shared Razorpay Server Instance
export const razorpay = new Razorpay({
  key_id: process.env.RAZORPAY_KEY_ID || process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || "",
  key_secret: process.env.RAZORPAY_KEY_SECRET || "",
});

/**
 * Verifies standard checkout payment signature generated by Razorpay.
 * Formula: HMAC-SHA256(razorpay_order_id + "|" + razorpay_payment_id, secret)
 */
export function verifyPaymentSignature({
  orderId,
  paymentId,
  signature,
}: {
  orderId: string;
  paymentId: string;
  signature: string;
}): boolean {
  const secret = process.env.RAZORPAY_KEY_SECRET;
  if (!secret || !orderId || !paymentId || !signature) {
    console.error("verifyPaymentSignature missing required parameters or secret");
    return false;
  }

  try {
    const expectedSignature = crypto
      .createHmac("sha256", secret)
      .update(`${orderId}|${paymentId}`)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature, "utf-8");
    const signatureBuffer = Buffer.from(signature, "utf-8");

    if (expectedBuffer.length !== signatureBuffer.length) {
      return false;
    }

    return crypto.timingSafeEqual(expectedBuffer, signatureBuffer);
  } catch (error) {
    console.error("Error verifying payment signature:", error);
    return false;
  }
}

/**
 * Verifies Razorpay Webhook signature from the `x-razorpay-signature` header.
 * Formula: HMAC-SHA256(rawRequestBody, webhookSecret)
 */
export function verifyWebhookSignature(rawBody: string, signature: string): boolean {
  const webhookSecret = process.env.RAZORPAY_WEBHOOK_SECRET;
  if (!webhookSecret || !rawBody || !signature) {
    console.error("verifyWebhookSignature missing required parameters or secret");
    return false;
  }

  try {
    const expectedSignature = crypto
      .createHmac("sha256", webhookSecret)
      .update(rawBody)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature, "utf-8");
    const signatureBuffer = Buffer.from(signature, "utf-8");

    if (expectedBuffer.length !== signatureBuffer.length) {
      return false;
    }

    return crypto.timingSafeEqual(expectedBuffer, signatureBuffer);
  } catch (error) {
    console.error("Error verifying webhook signature:", error);
    return false;
  }
}

/**
 * Decrements stock for all items associated with an order upon payment confirmation.
 * Tries the atomic Supabase RPC `deduct_order_stock` first, and falls back to a query-based loop.
 */
export async function deductOrderStock(orderId: string): Promise<{ success: boolean; error?: string }> {
  try {
    if (!orderId) {
      return { success: false, error: "Missing orderId" };
    }

    // 1. Try atomic database RPC function if created in Supabase
    try {
      const { error: rpcError } = await mysupabase.rpc("deduct_order_stock", {
        p_order_id: orderId,
      });

      if (!rpcError) {
        return { success: true };
      }
      // If function doesn't exist, fall through to query fallback
    } catch {
      // Fall through to fallback
    }

    // 2. Fallback: Fetch order_items and update product_variants directly
    const { data: orderItems, error: itemsError } = await mysupabase
      .from("order_items")
      .select("variant_id, quantity")
      .eq("order_id", orderId);

    if (itemsError || !orderItems || orderItems.length === 0) {
      return { success: false, error: itemsError?.message || "No order items found" };
    }

    for (const item of orderItems) {
      if (!item.variant_id) continue;

      const qty = Number(item.quantity) || 1;

      // Fetch current stock
      const { data: variant, error: varError } = await mysupabase
        .from("product_variants")
        .select("stock")
        .eq("id", item.variant_id)
        .single();

      if (varError || !variant) continue;

      const currentStock = Number(variant.stock) || 0;
      const updatedStock = Math.max(0, currentStock - qty);

      await mysupabase
        .from("product_variants")
        .update({ stock: updatedStock })
        .eq("id", item.variant_id);
    }

    return { success: true };
  } catch (error: any) {
    console.error(`Error deducting stock for order ${orderId}:`, error);
    return { success: false, error: error?.message || "Unknown error" };
  }
}
